// ANSI colors
const BLUE: &str = "\x1b[0;34m";
const RED: &str = "\x1b[0;31m";
const RESET: &str = "\x1b[0m";

fn blue(s: &str) -> String {
    format!("{}{}{}", BLUE, s, RESET)
}

fn error(msg: &str) {
    eprintln!("{}error{}: {}", RED, RESET, msg);
}

