// Simple TOML-like parser
struct SimpleToml {
    sections: HashMap<String, HashMap<String, String>>,
    root: HashMap<String, String>,
}

impl SimpleToml {
    fn new() -> Self {
        SimpleToml {
            sections: HashMap::new(),
            root: HashMap::new(),
        }
    }

    fn parse(content: &str) -> Self {
        let mut toml = SimpleToml::new();
        let mut current_section: Option<String> = None;

        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if line.starts_with('[') && line.ends_with(']') {
                current_section = Some(line[1..line.len()-1].to_string());
                toml.sections.entry(current_section.clone().unwrap()).or_insert_with(HashMap::new);
                continue;
            }
            if let Some(eq_pos) = line.find('=') {
                let key = line[..eq_pos].trim().to_string();
                let val_raw = line[eq_pos+1..].trim();
                let value = parse_toml_value(val_raw);

                // Handle quoted keys
                let key = if key.starts_with('"') && key.ends_with('"') {
                    key[1..key.len()-1].to_string()
                } else {
                    key
                };

                if let Some(ref section) = current_section {
                    toml.sections.entry(section.clone()).or_insert_with(HashMap::new).insert(key, value);
                } else {
                    toml.root.insert(key, value);
                }
            }
        }
        toml
    }

    fn get(&self, key: &str) -> Option<&String> {
        self.root.get(key)
    }

    fn get_section(&self, section: &str, key: &str) -> Option<&String> {
        self.sections.get(section)?.get(key)
    }

    fn section_entries(&self, section: &str) -> Vec<(String, String)> {
        match self.sections.get(section) {
            Some(map) => {
                let mut entries: Vec<(String, String)> = map.iter()
                    .map(|(k, v)| (k.clone(), v.clone()))
                    .collect();
                entries.sort_by(|a, b| a.0.cmp(&b.0));
                entries
            }
            None => vec![],
        }
    }
}

fn parse_toml_value(s: &str) -> String {
    if (s.starts_with('\'') && s.ends_with('\'')) ||
       (s.starts_with('"') && s.ends_with('"')) {
        s[1..s.len()-1].to_string()
    } else {
        s.to_string()
    }
}

fn toml_key(key: &str) -> String {
    // If key contains special chars, quote it
    if key.chars().any(|c| c == ' ' || c == '-' || c == '.') {
        format!("\"{}\"", key)
    } else {
        key.to_string()
    }
}

fn toml_string_value(val: &str) -> String {
    format!("'{}'", val)
}

// Config structure
struct Config {
    editor: String,
    conflict: bool,
}

impl Config {
    fn load() -> Self {
        let path = config_path();
        if !path.exists() {
            return Config {
                editor: String::new(),
                conflict: true,
            };
        }
        let content = fs::read_to_string(&path).unwrap_or_default();
        let toml = SimpleToml::parse(&content);
        let editor = toml.get("editor").cloned().unwrap_or_default();
        let conflict = toml.get("conflict")
            .map(|v| v == "true")
            .unwrap_or(true);
        Config { editor, conflict }
    }

    fn save(&self) {
        let dir = config_dir();
        fs::create_dir_all(&dir).ok();
        let content = format!(
            "editor = '{}'\nconflict = {}\n",
            self.editor,
            self.conflict
        );
        fs::write(config_path(), content).ok();
    }
}

// Vaults data
struct VaultsData {
    current: Option<String>,
    vaults: Vec<(String, String)>, // (name, location) in order
}

impl VaultsData {
    fn load() -> Self {
        let path = vaults_path();
        if !path.exists() {
            return VaultsData { current: None, vaults: vec![] };
        }
        let content = fs::read_to_string(&path).unwrap_or_default();
        let toml = SimpleToml::parse(&content);
        let current = toml.get("current").cloned();

        // We need to preserve order, so we parse manually
        let mut vaults = vec![];
        let mut in_vaults = false;
        for line in content.lines() {
            let line_trim = line.trim();
            if line_trim == "[vaults]" {
                in_vaults = true;
                continue;
            }
            if line_trim.starts_with('[') {
                in_vaults = false;
                continue;
            }
            if in_vaults {
                if let Some(eq_pos) = line_trim.find('=') {
                    let key = line_trim[..eq_pos].trim();
                    let val_raw = line_trim[eq_pos+1..].trim();
                    let value = parse_toml_value(val_raw);
                    let key = if key.starts_with('"') && key.ends_with('"') {
                        key[1..key.len()-1].to_string()
                    } else {
                        key.to_string()
                    };
                    vaults.push((key, value));
                }
            }
        }

        VaultsData { current, vaults }
    }

    fn save(&self) {
        let dir = data_dir();
        fs::create_dir_all(&dir).ok();
        let mut content = String::new();
        if let Some(ref current) = self.current {
            content.push_str(&format!("current = '{}'\n\n", current));
        }
        content.push_str("[vaults]\n");
        for (name, location) in &self.vaults {
            content.push_str(&format!("{} = '{}'\n", toml_key(name), location));
        }
        fs::write(vaults_path(), content).ok();
    }

    fn get_vault_location(&self, name: &str) -> Option<&str> {
        self.vaults.iter()
            .find(|(n, _)| n == name)
            .map(|(_, l)| l.as_str())
    }

    fn add_vault(&mut self, name: String, location: String) {
        self.vaults.push((name, location));
    }

    fn remove_vault(&mut self, name: &str) {
        self.vaults.retain(|(n, _)| n != name);
        if self.current.as_deref() == Some(name) {
            self.current = None;
        }
    }
}

// Vault data structure
struct VaultData {
    name: String,
    location: String,
    folder: String,
    history: Vec<String>,
}

impl VaultData {
    fn load(vault_path: &Path) -> Option<Self> {
        let data_path = vault_path.join(".jot").join("data");
        if !data_path.exists() {
            return None;
        }
        let content = fs::read_to_string(&data_path).ok()?;
        let toml = SimpleToml::parse(&content);

        let name = toml.get("name")?.clone();
        let location = toml.get("location")?.clone();
        let folder = toml.get("folder").cloned().unwrap_or_default();

        Some(VaultData {
            name,
            location,
            folder,
            history: vec![],
        })
    }

    fn save(&self, vault_path: &Path) {
        let jot_dir = vault_path.join(".jot");
        fs::create_dir_all(&jot_dir).ok();
        let history_str = format!("[{}]", self.history.iter()
            .map(|h| format!("'{}'", h))
            .collect::<Vec<_>>()
            .join(", "));
        let content = format!(
            "name = '{}'\nlocation = '{}'\nfolder = '{}'\nhistory = {}\n",
            self.name, self.location, self.folder, history_str
        );
        fs::write(jot_dir.join("data"), content).ok();
    }

    fn vault_root(&self) -> PathBuf {
        PathBuf::from(&self.location).join(&self.name)
    }

    fn current_folder_path(&self) -> PathBuf {
        let root = self.vault_root();
        if self.folder.is_empty() {
            root
        } else {
            root.join(&self.folder)
        }
    }
}

// Validate a name (no slashes)
fn validate_name(name: &str) -> bool {
    !name.contains('/')
}

fn get_current_vault() -> Option<(VaultsData, VaultData)> {
    let vdata = VaultsData::load();
    let current = vdata.current.clone()?;
    let location = vdata.get_vault_location(&current)?.to_string();
    let vault_path = PathBuf::from(&location).join(&current);
    let vault = VaultData::load(&vault_path)?;
    Some((vdata, vault))
}

// Print tree of directory contents
fn print_tree(path: &Path, prefix: &str, is_last: bool, root_name: &str, notes_only: bool, folders_only: bool) {
    // This is called for contents of a directory
    let entries = match read_dir_sorted(path) {
        Ok(e) => e,
        Err(_) => return,
    };

    // Filter entries based on notes_only/folders_only
    let filtered: Vec<_> = entries.iter().filter(|entry| {
        if notes_only {
            entry.is_file() && entry.extension().map(|e| e == "md").unwrap_or(false)
        } else if folders_only {
            entry.is_dir()
        } else {
            // Default: show all except .jot
            let name = entry.file_name().unwrap_or_default().to_string_lossy();
            !(name == ".jot" && entry.is_dir())
        }
    }).collect();

    for (i, entry) in filtered.iter().enumerate() {
        let is_last_entry = i == filtered.len() - 1;
        let connector = if is_last_entry { "└── " } else { "├── " };
        let entry_name = entry.file_name().unwrap_or_default().to_string_lossy().to_string();

        let is_note = entry.is_file() && entry.extension().map(|e| e == "md").unwrap_or(false);
        let display_name = if is_note {
            let stem = Path::new(&entry_name).file_stem()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or(entry_name.clone());
            blue(&stem)
        } else {
            entry_name.clone()
        };

        println!("{}{}{}", prefix, connector, display_name);

        if entry.is_dir() && !notes_only {
            let new_prefix = format!("{}{}   ", prefix, if is_last_entry { " " } else { "│" });
            print_tree(entry, &new_prefix, is_last_entry, root_name, notes_only, folders_only);
        }
    }
}

fn read_dir_sorted(path: &Path) -> io::Result<Vec<PathBuf>> {
    let mut entries: Vec<PathBuf> = fs::read_dir(path)?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .collect();
    entries.sort_by(|a, b| {
        let a_name = a.file_name().unwrap_or_default().to_string_lossy().to_lowercase();
        let b_name = b.file_name().unwrap_or_default().to_string_lossy().to_lowercase();
        // Sort: directories first by name, then files by name? Let me check
        // Actually from examples, it seems entries are in insertion order mostly
        // Let me use plain sort
        a.file_name().unwrap_or_default().to_string_lossy()
            .cmp(&b.file_name().unwrap_or_default().to_string_lossy())
    });
    Ok(entries)
}

fn cmd_vault(args: &[String]) {
    // vault [name] [location] or vault -l
    if args.is_empty() {
        // List vaults
        let vdata = VaultsData::load();
        for (name, _) in &vdata.vaults {
            let is_current = vdata.current.as_deref() == Some(name);
            if is_current {
                println!("👉 {}", blue(name));
            } else {
                println!("   {}", name);
            }
        }
        return;
    }

    if args[0] == "-l" {
        // List vaults with locations
        let vdata = VaultsData::load();
        for (name, location) in &vdata.vaults {
            let is_current = vdata.current.as_deref() == Some(name);
            if is_current {
                println!("👉 {} \t {}", blue(name), location);
            } else {
                println!("   {} \t {}", name, location);
            }
        }
        return;
    }

    if args[0] == "-h" || args[0] == "--help" {
        print_vault_help();
        return;
    }

    if args.len() < 2 {
        // Invalid usage
        print_vault_help();
        return;
    }

    let vault_name = &args[0];
    let vault_location = &args[1];

    // Validate name
    if !validate_name(vault_name) {
        error("invalid name");
        return;
    }

    // Check location exists
    let location_path = Path::new(vault_location);
    if !location_path.exists() {
        error("couldn't find the path specified");
        return;
    }

    let vault_path = location_path.join(vault_name);

    // Check if vault already exists
    let mut vdata = VaultsData::load();
    if vdata.get_vault_location(vault_name).is_some() {
        error(&format!("vault {} already exists", vault_name));
        return;
    }

    // Create vault directory
    if vault_path.exists() {
        error(&format!("a folder named {} already exists in this location", vault_name));
        return;
    }

    if let Err(e) = fs::create_dir_all(vault_path.join(".jot")) {
        error(&format!("failed to create vault: {}", e));
        return;
    }

    // Write vault data file
    let vaultdata = VaultData {
        name: vault_name.clone(),
        location: vault_location.to_string(),
        folder: String::new(),
        history: vec![],
    };
    vaultdata.save(&vault_path);

    // Update vaults file
    vdata.add_vault(vault_name.clone(), vault_location.to_string());
    vdata.save();

    println!("vault {} created", blue(vault_name));
}

