fn cmd_open(args: &[String]) {
    if args.is_empty() || args[0] == "-h" || args[0] == "--help" {
        if args.is_empty() {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <note name>");
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    executable open <note name>");
            eprintln!();
            eprintln!("For more information try --help");
            process::exit(2);
        }
        print_open_help();
        return;
    }

    let note_name = &args[0];

    let config = Config::load();
    if config.editor.is_empty() {
        error("editor not found");
        return;
    }

    let (vdata, vault) = match get_current_vault() {
        Some(v) => v,
        None => {
            error("not inside a vault");
            return;
        }
    };

    let folder = vault.current_folder_path();
    let note_path = folder.join(format!("{}.md", note_name));

    if !note_path.exists() {
        error(&format!("note {} not found", note_name));
        return;
    }

    // Check if editor exists
    let editor_path = if config.editor.starts_with('/') {
        PathBuf::from(&config.editor)
    } else {
        // Try to find in PATH
        which_cmd(&config.editor)
    };

    let editor = match editor_path {
        p if p.exists() => p,
        _ => {
            error("editor not found");
            return;
        }
    };

    process::Command::new(editor)
        .arg(&note_path)
        .status()
        .ok();
}

fn which_cmd(cmd: &str) -> PathBuf {
    if let Ok(path_var) = std::env::var("PATH") {
        for dir in path_var.split(':') {
            let p = PathBuf::from(dir).join(cmd);
            if p.exists() {
                return p;
            }
        }
    }
    PathBuf::from(cmd)
}

