// Simple TOML-like parser
struct SimpleToml {
    sections: HashMap<String, HashMap<String, String>>,
    root: HashMap<String, String>,
}

impl SimpleToml {
    fn new() -> Self {
        SimpleToml {
            sections: HashMap::new(),
            root: HashMap::new(),
        }
    }

    fn parse(content: &str) -> Self {
        let mut toml = SimpleToml::new();
        let mut current_section: Option<String> = None;

        for line in content.lines() {
            let line = line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if line.starts_with('[') && line.ends_with(']') {
                current_section = Some(line[1..line.len()-1].to_string());
                toml.sections.entry(current_section.clone().unwrap()).or_insert_with(HashMap::new);
                continue;
            }
            if let Some(eq_pos) = line.find('=') {
                let key = line[..eq_pos].trim().to_string();
                let val_raw = line[eq_pos+1..].trim();
                let value = parse_toml_value(val_raw);

                // Handle quoted keys
                let key = if key.starts_with('"') && key.ends_with('"') {
                    key[1..key.len()-1].to_string()
                } else {
                    key
                };

                if let Some(ref section) = current_section {
                    toml.sections.entry(section.clone()).or_insert_with(HashMap::new).insert(key, value);
                } else {
                    toml.root.insert(key, value);
                }
            }
        }
        toml
    }

    fn get(&self, key: &str) -> Option<&String> {
        self.root.get(key)
    }

    fn get_section(&self, section: &str, key: &str) -> Option<&String> {
        self.sections.get(section)?.get(key)
    }

    fn section_entries(&self, section: &str) -> Vec<(String, String)> {
        match self.sections.get(section) {
            Some(map) => {
                let mut entries: Vec<(String, String)> = map.iter()
                    .map(|(k, v)| (k.clone(), v.clone()))
                    .collect();
                entries.sort_by(|a, b| a.0.cmp(&b.0));
                entries
            }
            None => vec![],
        }
    }
}

fn parse_toml_value(s: &str) -> String {
    if (s.starts_with('\'') && s.ends_with('\'')) ||
       (s.starts_with('"') && s.ends_with('"')) {
        s[1..s.len()-1].to_string()
    } else {
        s.to_string()
    }
}

fn toml_key(key: &str) -> String {
    // If key contains special chars, quote it
    if key.chars().any(|c| c == ' ' || c == '-' || c == '.') {
        format!("\"{}\"", key)
    } else {
        key.to_string()
    }
}

