        let content = fs::read_to_string(&path).unwrap_or_default();
        let toml = SimpleToml::parse(&content);
        let current = toml.get("current").cloned();

        // We need to preserve order, so we parse manually
        let mut vaults = vec![];
        let mut in_vaults = false;
        for line in content.lines() {
            let line_trim = line.trim();
            if line_trim == "[vaults]" {
                in_vaults = true;
                continue;
            }
            if line_trim.starts_with('[') {
                in_vaults = false;
                continue;
            }
            if in_vaults {
                if let Some(eq_pos) = line_trim.find('=') {
                    let key = line_trim[..eq_pos].trim();
                    let val_raw = line_trim[eq_pos+1..].trim();
                    let value = parse_toml_value(val_raw);
                    let key = if key.starts_with('"') && key.ends_with('"') {
                        key[1..key.len()-1].to_string()
                    } else {
                        key.to_string()
                    };
                    vaults.push((key, value));
                }
            }
        }

        VaultsData { current, vaults }
