        } else {
            entry_name.clone()
        };

        println!("{}{}{}", prefix, connector, display_name);

        if entry.is_dir() && !notes_only {
            let new_prefix = format!("{}{}   ", prefix, if is_last_entry { " " } else { "│" });
            print_tree(entry, &new_prefix, is_last_entry, root_name, notes_only, folders_only);
        }
    }
}

fn read_dir_sorted(path: &Path) -> io::Result<Vec<PathBuf>> {
    let mut entries: Vec<PathBuf> = fs::read_dir(path)?
        .filter_map(|e| e.ok().map(|e| e.path()))
        .collect();
    entries.sort_by(|a, b| {
        let a_name = a.file_name().unwrap_or_default().to_string_lossy().to_lowercase();
        let b_name = b.file_name().unwrap_or_default().to_string_lossy().to_lowercase();
