fn cmd_rename(args: &[String]) {
    if args.is_empty() || args[0] == "-h" || args[0] == "--help" {
        if args.is_empty() {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <item type>");
            eprintln!("    <name>");
            eprintln!("    <new name>");
            process::exit(2);
        }
        print_rename_help();
        return;
    }

    let item_type = &args[0];
    if args.len() < 3 {
        eprintln!("error: Not enough arguments");
        process::exit(2);
    }
    let name = &args[1];
    let new_name = &args[2];

    if !validate_name(new_name) {
        error("invalid name");
        return;
    }

    match item_type.as_str() {
        "vault" | "vl" => {
            let mut vdata = VaultsData::load();
            if vdata.get_vault_location(name).is_none() {
                error(&format!("vault {} doesn't exist", name));
                return;
            }

            let location = vdata.get_vault_location(name).unwrap().to_string();
            let old_vault_path = PathBuf::from(&location).join(name);
            let new_vault_path = PathBuf::from(&location).join(new_name);

            if new_vault_path.exists() {
                error(&format!("a vault named {} already exists", new_name));
                return;
            }

            // Rename the directory
            fs::rename(&old_vault_path, &new_vault_path).ok();

            // Update vault data file
            if let Some(mut vault) = VaultData::load(&new_vault_path) {
                vault.name = new_name.clone();
                vault.save(&new_vault_path);
            }

            // Update vaults file
            let is_current = vdata.current.as_deref() == Some(name.as_str());
            for entry in &mut vdata.vaults {
                if entry.0 == *name {
                    entry.0 = new_name.clone();
                    break;
                }
            }
            if is_current {
                vdata.current = Some(new_name.clone());
            }
            vdata.save();

            println!("vault {} renamed to {}", blue(name), blue(new_name));
        }
        "note" | "nt" => {
            let (vdata, vault) = match get_current_vault() {
                Some(v) => v,
                None => {
                    error("not inside a vault");
                    return;
                }
            };

            let folder = vault.current_folder_path();
            let old_path = folder.join(format!("{}.md", name));
            let new_path = folder.join(format!("{}.md", new_name));

            if !old_path.exists() {
                error(&format!("note {} not found", name));
                return;
            }

            if new_path.exists() {
                error(&format!("a note named {} already exists in this location", new_name));
                return;
            }

            fs::rename(&old_path, &new_path).ok();
            println!("note {} renamed to {}", blue(name), blue(new_name));
        }
        "folder" | "fd" => {
            let (vdata, vault) = match get_current_vault() {
                Some(v) => v,
                None => {
                    error("not inside a vault");
                    return;
                }
            };

            let folder = vault.current_folder_path();
            let old_path = folder.join(name);
            let new_path = folder.join(new_name);

            if !old_path.exists() || !old_path.is_dir() {
                error(&format!("folder {} not found", name));
                return;
            }

            if new_path.exists() {
                error(&format!("a folder named {} already exists in this location", new_name));
                return;
            }

            fs::rename(&old_path, &new_path).ok();
            println!("folder {} renamed to {}", blue(name), blue(new_name));
        }
        _ => {
            eprintln!("error: {:?} isn't a valid value for '<item type>'", item_type);
            eprintln!("\t[possible values: vault, vl, note, nt, folder, fd]");
            eprintln!();
            eprintln!("For more information try --help");
            process::exit(2);
        }
    }
}

