        }
        print_move_help();
        return;
    }

    let item_type = &args[0];
    if args.len() < 3 {
        eprintln!("error: Not enough arguments");
        process::exit(2);
    }
    let name = &args[1];
    let new_location = &args[2];

    match item_type.as_str() {
        "vault" | "vl" => {
            let mut vdata = VaultsData::load();
            if vdata.get_vault_location(name).is_none() {
                error(&format!("vault {} doesn't exist", name));
                return;
            }

            let old_location = vdata.get_vault_location(name).unwrap().to_string();

            if old_location == *new_location {
                error("new location is same as old location");
                return;
            }

            let new_loc_path = Path::new(new_location);
            if !new_loc_path.exists() {
                match fs::metadata(new_loc_path) {
                    Err(e) => {
                        error(&format!("{}", e));
                        return;
                    }
                    _ => {}
                }
            }

            let new_vault_path = new_loc_path.join(name);
            if new_vault_path.exists() {
                error(&format!("a folder named {} already exists in this location", name));
                return;
            }

            let old_vault_path = PathBuf::from(&old_location).join(name);

            // Move directory
            if let Err(e) = fs::rename(&old_vault_path, &new_vault_path) {
                error(&format!("{}", e));
                return;
            }

            // Update vault data
            if let Some(mut vault) = VaultData::load(&new_vault_path) {
                vault.location = new_location.to_string();
                vault.save(&new_vault_path);
            }

            // Update vaults file
            for entry in &mut vdata.vaults {
                if entry.0 == *name {
                    entry.1 = new_location.to_string();
                    break;
                }
            }
            vdata.save();

            println!("vault {} moved", blue(name));
        }
        "note" | "nt" => {
            let (vdata, vault) = match get_current_vault() {
                Some(v) => v,
                None => {
                    error("not inside a vault");
                    return;
                }
