fn cmd_chdir(args: &[String]) {
    if args.is_empty() || args[0] == "-h" || args[0] == "--help" {
        if args.is_empty() {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <folder path>");
            eprintln!();
            eprintln!("USAGE:");
            eprintln!("    executable chdir <folder path>");
            eprintln!();
            eprintln!("For more information try --help");
            process::exit(2);
        }
        print_chdir_help();
        return;
    }

    let path_arg = &args[0];

    let (vdata, mut vault) = match get_current_vault() {
        Some(v) => v,
        None => {
            error("not inside a vault");
            return;
        }
    };

    let vault_root = vault.vault_root();
    let current = vault.current_folder_path();

    // Compute new path
    let new_path = if path_arg == ".." {
        current.parent().map(|p| p.to_path_buf()).unwrap_or(current.clone())
    } else {
        current.join(path_arg)
    };

    // Canonicalize and check bounds
    let new_canonical = match new_path.canonicalize() {
        Ok(p) => p,
        Err(_) => {
            error("couldn't find the path specified");
            return;
        }
    };

    let root_canonical = match vault_root.canonicalize() {
        Ok(p) => p,
        Err(_) => {
            error("couldn't find the path specified");
            return;
        }
    };

    if !new_canonical.starts_with(&root_canonical) {
        error("path crosses the bounds of vault");
        return;
    }

    if !new_canonical.is_dir() {
        error("couldn't find the path specified");
        return;
    }

    // Compute relative folder path
    let relative = new_canonical.strip_prefix(&root_canonical)
        .unwrap_or(Path::new(""))
        .to_string_lossy()
        .to_string();

    vault.folder = relative;
    vault.save(&vault_root);

    println!("folder changed");
}

