    if args.is_empty() || args[0] == "-h" || args[0] == "--help" {
        if args.is_empty() {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <item type>");
            eprintln!("    <name>");
            eprintln!("    <new location>");
            process::exit(2);
        }
        print_move_help();
        return;
    }

    let item_type = &args[0];
    if args.len() < 3 {
        eprintln!("error: Not enough arguments");
        process::exit(2);
    }
    let name = &args[1];
    let new_location = &args[2];

    match item_type.as_str() {
        "vault" | "vl" => {
            let mut vdata = VaultsData::load();
            if vdata.get_vault_location(name).is_none() {
                error(&format!("vault {} doesn't exist", name));
                return;
            }

            let old_location = vdata.get_vault_location(name).unwrap().to_string();

            if old_location == *new_location {
                error("new location is same as old location");
                return;
            }

            let new_loc_path = Path::new(new_location);
            if !new_loc_path.exists() {
                match fs::metadata(new_loc_path) {
                    Err(e) => {
                        error(&format!("{}", e));
                        return;
                    }
                    _ => {}
                }
            }

            let new_vault_path = new_loc_path.join(name);
            if new_vault_path.exists() {
                error(&format!("a folder named {} already exists in this location", name));
                return;
            }

            let old_vault_path = PathBuf::from(&old_location).join(name);

            // Move directory
            if let Err(e) = fs::rename(&old_vault_path, &new_vault_path) {
                error(&format!("{}", e));
                return;
            }

            // Update vault data
            if let Some(mut vault) = VaultData::load(&new_vault_path) {
                vault.location = new_location.to_string();
                vault.save(&new_vault_path);
            }

            // Update vaults file
            for entry in &mut vdata.vaults {
                if entry.0 == *name {
                    entry.1 = new_location.to_string();
                    break;
                }
            }
            vdata.save();

            println!("vault {} moved", blue(name));
        }
        "note" | "nt" => {
            let (vdata, vault) = match get_current_vault() {
                Some(v) => v,
                None => {
                    error("not inside a vault");
                    return;
                }
            };

            let vault_root = vault.vault_root();
            let current = vault.current_folder_path();
            let old_note_path = current.join(format!("{}.md", name));

            if !old_note_path.exists() {
                error(&format!("note {} not found", name));
                return;
            }

            // Compute new path (relative to current folder)
            let new_dir = current.join(new_location);
            let new_dir_canonical = match new_dir.canonicalize() {
                Ok(p) => p,
                Err(_) => {
                    error("couldn't find the path specified");
                    return;
                }
            };

            let vault_root_canonical = vault_root.canonicalize().unwrap();

            if !new_dir_canonical.starts_with(&vault_root_canonical) {
                error("path crosses the bounds of vault");
                return;
            }

            let new_note_path = new_dir_canonical.join(format!("{}.md", name));

            if new_note_path.exists() {
                error(&format!("a note named {} already exists in this location", name));
                return;
            }

            if let Err(e) = fs::rename(&old_note_path, &new_note_path) {
                error(&format!("{}", e));
                return;
            }

            println!("note {} moved", blue(name));
        }
        "folder" | "fd" => {
            let (vdata, vault) = match get_current_vault() {
                Some(v) => v,
                None => {
                    error("not inside a vault");
                    return;
                }
            };

            let vault_root = vault.vault_root();
            let current = vault.current_folder_path();
            let old_folder_path = current.join(name);

            if !old_folder_path.exists() || !old_folder_path.is_dir() {
                error(&format!("folder {} not found", name));
                return;
            }

            let new_dir = current.join(new_location);
            let new_dir_canonical = match new_dir.canonicalize() {
                Ok(p) => p,
                Err(_) => {
                    error("couldn't find the path specified");
                    return;
                }
            };

            let vault_root_canonical = vault_root.canonicalize().unwrap();

            if !new_dir_canonical.starts_with(&vault_root_canonical) {
                error("path crosses the bounds of vault");
                return;
            }

            let new_folder_path = new_dir_canonical.join(name);

            if new_folder_path.exists() {
                error(&format!("a folder named {} already exists in this location", name));
                return;
            }

            if let Err(e) = fs::rename(&old_folder_path, &new_folder_path) {
                error(&format!("{}", e));
                return;
            }

            println!("folder {} moved", blue(name));
        }
        _ => {
            eprintln!("error: {:?} isn't a valid value for '<item type>'", item_type);
            eprintln!("\t[possible values: vault, vl, note, nt, folder, fd]");
            eprintln!();
