    println!("    <name>            name of item to be moved");
    println!("    <new location>    path to new location of item (current folder as root in case of note or");
    println!("                      folder)");
    println!();
    println!("OPTIONS:");
    println!("    -h, --help    Print help information");
}

fn cmd_vmove(args: &[String]) {
    if args.is_empty() || args[0] == "-h" || args[0] == "--help" {
        if args.is_empty() {
            eprintln!("error: The following required arguments were not provided:");
            eprintln!("    <item type>");
            eprintln!("    <name>");
            eprintln!("    <vault name>");
            process::exit(2);
        }
        print_vmove_help();
        return;
    }

    let item_type = &args[0];
    if args.len() < 3 {
        eprintln!("error: Not enough arguments");
        process::exit(2);
    }
    let name = &args[1];
    let vault_name = &args[2];

    let (src_vdata, src_vault) = match get_current_vault() {
        Some(v) => v,
        None => {
            error("not inside a vault");
            return;
        }
    };

    let all_vdata = VaultsData::load();

    if all_vdata.get_vault_location(vault_name).is_none() {
        error(&format!("vault {} doesn't exist", vault_name));
        return;
    }

    let dest_vault_location = all_vdata.get_vault_location(vault_name).unwrap().to_string();
    let dest_vault_path = PathBuf::from(&dest_vault_location).join(vault_name);

    match item_type.as_str() {
        "note" | "nt" => {
            let current = src_vault.current_folder_path();
            let old_path = current.join(format!("{}.md", name));

            if !old_path.exists() {
                match fs::metadata(&old_path) {
                    Err(e) => {
                        error(&format!("{}", e));
                        return;
                    }
                    _ => {}
                }
            }

            let new_path = dest_vault_path.join(format!("{}.md", name));

            if let Err(e) = fs::rename(&old_path, &new_path) {
                error(&format!("{}", e));
                return;
            }

            println!("note {} moved to vault {}", blue(name), blue(vault_name));
        }
        "folder" | "fd" => {
            let current = src_vault.current_folder_path();
            let old_path = current.join(name);

            if !old_path.exists() {
                match fs::metadata(&old_path) {
                    Err(e) => {
                        error(&format!("{}", e));
                        return;
                    }
                    _ => {}
                }
            }

            let new_path = dest_vault_path.join(name);

            if let Err(e) = fs::rename(&old_path, &new_path) {
                error(&format!("{}", e));
                return;
            }

            println!("folder {} moved to vault {}", blue(name), blue(vault_name));
        }
        _ => {
            eprintln!("error: {:?} isn't a valid value for '<item type>'", item_type);
            eprintln!("\t[possible values: note, nt, folder, fd]");
            eprintln!();
            eprintln!("For more information try --help");
            process::exit(2);
        }
    }
}

fn print_vmove_help() {
    println!("executable-vmove ");
    println!("move notes and folders to a different vault");
    println!();
    println!("USAGE:");
    println!("    executable vmove <item type> <name> <vault name>");
    println!();
    println!("ARGS:");
    println!("    <item type>     move a note (or nt) | folder (or fd)");
    println!("    <name>          name of item to be moved");
    println!("    <vault name>    name of vault to move the item to");
    println!();
    println!("OPTIONS:");
    println!("    -h, --help    Print help information");
}

fn cmd_config(args: &[String]) {
    if !args.is_empty() && (args[0] == "-h" || args[0] == "--help") {
        print_config_help();
        return;
    }

    if args.is_empty() {
        // Open config in editor
        let config = Config::load();
        if config.editor.is_empty() {
            error("editor not found");
            return;
        }

        let editor_path = if config.editor.starts_with('/') {
            PathBuf::from(&config.editor)
        } else {
            which_cmd(&config.editor)
        };

        let editor = if editor_path.exists() {
            editor_path
        } else {
            error("editor not found");
            return;
        };

        let config_file = config_path();
        process::Command::new(editor)
            .arg(&config_file)
            .status()
            .ok();
        return;
    }

    let config_type = &args[0];

    match config_type.as_str() {
        "editor" => {
            if args.len() >= 2 {
                let mut config = Config::load();
                config.editor = args[1].clone();
                config.save();
                println!("set {} to {}", blue("editor"), blue(&args[1]));
            } else {
                let config = Config::load();
                println!("editor: {}", blue(&config.editor));
            }
        }
        "conflict" => {
            if args.len() >= 2 {
                let val = &args[1];
                let mut config = Config::load();
                config.conflict = val == "true";
                config.save();
                println!("set {} to {}", blue("conflict"), blue(val));
            } else {
                let config = Config::load();
                println!("conflict: {}", blue(&config.conflict.to_string()));
            }
        }
        _ => {
            eprintln!("error: {:?} isn't a valid value for '<config type>'", config_type);
            eprintln!("\t[possible values: editor, conflict]");
            eprintln!();
            eprintln!("For more information try --help");
            process::exit(2);
        }
    }
}

