    println!();
    print!("{}", BLUE);
    print!("commands:");
    println!("{}", RESET);
    println!();
    println!("create items");
    println!("    {}, {}       create a vault or list vaults", blue("vault"), blue("vl"));
    println!("    create items in current folder");
    println!("        {}, {}        create a note ", blue("note"), blue("nt"));
    println!("        {}, {}      create a folder", blue("folder"), blue("fd"));
    println!();
