    println!("    {}, {}        open a note from current folder", blue("open"), blue("op"));
    println!("    {}, {}       open current folder in file explorer", blue("opdir"), blue("od"));
    println!("    {}, {}       change folder within current vault", blue("chdir"), blue("cd"));
    println!("    {}, {}        list items in current folder", blue("list"), blue("ls"));
    println!();
    println!("perform fs operations on items");
    println!("    {}, {}      remove an item ", blue("remove"), blue("rm"));
    println!("    {}, {}      rename an item ", blue("rename"), blue("rn"));
    println!("    {}, {}        move an item to a new location", blue("move"), blue("mv"));
    println!("    {}, {}       move an item to a different vault", blue("vmove"), blue("vm"));
    println!();
    println!("config");
    println!("    {}, {}      display, set or open config", blue("config"), blue("cf"));
    println!();
    println!("get help ");
    println!("    use {} or {} and {} flags along with a command to get corresponding help", 
             blue("help"), blue("-h"), blue("--help"));
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    if args.len() < 2 {
        print_help();
        return;
    }

    let command = &args[1];
    let rest = &args[2..];

    match command.as_str() {
        "vault" | "vl" => cmd_vault(rest),
        "enter" | "en" => cmd_enter(rest),
        "note" | "nt" => cmd_note(rest),
        "folder" | "fd" => cmd_folder(rest),
        "open" | "op" => cmd_open(rest),
        "opdir" | "od" => cmd_opdir(rest),
        "chdir" | "cd" => cmd_chdir(rest),
        "list" | "ls" => cmd_list(rest),
        "remove" | "rm" => cmd_remove(rest),
        "rename" | "rn" => cmd_rename(rest),
        "move" | "mv" => cmd_move(rest),
        "vmove" | "vm" => cmd_vmove(rest),
        "config" | "cf" => cmd_config(rest),
        "help" | "-h" | "--help" => {
            if rest.is_empty() {
                print_help();
            } else {
                // Get help for a specific command
                let sub_cmd = &rest[0];
                match sub_cmd.as_str() {
                    "vault" | "vl" => print_vault_help(),
                    "enter" | "en" => print_enter_help(),
                    "note" | "nt" => print_note_help(),
                    "folder" | "fd" => print_folder_help(),
                    "open" | "op" => print_open_help(),
                    "opdir" | "od" => print_opdir_help(),
                    "chdir" | "cd" => print_chdir_help(),
                    "list" | "ls" => print_list_help(),
                    "remove" | "rm" => print_remove_help(),
                    "rename" | "rn" => print_rename_help(),
                    "move" | "mv" => print_move_help(),
                    "vmove" | "vm" => print_vmove_help(),
                    "config" | "cf" => print_config_help(),
                    _ => print_help(),
                }
            }
        }
        _ => {
            print_help();
        }
    }
}
